import logging
import os
import re
from typing import Dict, List, Optional

import paramiko

from taf.rfrl.scrambling_logs_collector.resources.python.globals import PROXY_VM_IPV4, PROXY_VM_IPV4_BACKUP, PROXY_VM_LOGIN, \
    PROXY_VM_PASSWORD, DIRECTORIES_TO_CLEAR
from taf.rfrl.scrambling_logs_collector.resources.python.logs_collector import LogsCollector
from taf.rfrl.scrambling_logs_collector.resources.python.logs_preparer import LogsPreparer
from taf.rfrl.scrambling_logs_collector.resources.python.utils import get_domain, get_domain_regex_by_log_type, \
    clear_directories, sftp_connection_available

logger = logging.getLogger(__name__)


def _get_latest_file(files: List[str]) -> str:
    """
    Get the latest file based on modification time.
    :param files:   List of file paths to compare
    :return:        Path to the latest file
    """
    if len(files) == 1:
        return files[0]

    # Sort by modification time (newest first)
    files_sorted = sorted(files, key=lambda f: os.path.getmtime(f), reverse=True)
    return files_sorted[0]


def check_for_existing_logs_in_dir(input_logs_dir: Optional[str], mandatory_log_type: str,
                                   team_name: str, pick_latest_only: bool = True) -> Dict[str, List[str]]:
    """
    Browse input_logs_dir dir recursively to find BTS logs which are already present on VM.
    Only the logs with selected input_log_types can be taken.

    NEW: Added pick_latest_only parameter for flexible file selection behavior.

    For vDU/vCU snapshots, the regex patterns in DOMAIN_FILE_REGEXES use folder structure
    (e.g., /vDU/ or /vCU/ in path) to distinguish between snapshot types.

    :param input_logs_dir:      Dir path on vm to the folder which contains the logs.
                                Can be a parent directory - will search recursively.
                                e.g., ~/MN/UTE/robotws or ${TEST_RESULTS_DIR}
    :param mandatory_log_type:  Log type which should be taken into account during the browsing
                                e.g., __snapshot_vDU__, __snapshot_vCU__
    :param team_name:           Delivery team name, i.e. PZ3WRO4, PZ3WRO5
    :param pick_latest_only:    If True (default), return only the latest file when multiple matches found.
                                If False, return all matching files. Useful for batch processing.
    :return:                    Map with collected logs. Returns latest file only if pick_latest_only=True.
                                Example: {'__snapshot_vDU__': ['/path/to/vDU/Snapshot_20260119-110614.zip']}
                                Or with pick_latest_only=False: {'__snapshot__': ['/path/file1.zip', '/path/file2.zip']}
    """
    logs_dir: Dict[str, List[str]] = {}
    if not input_logs_dir:
        return logs_dir
    domain = get_domain(team_name)

    if os.path.exists(input_logs_dir):
        matching_files: List[str] = []
        domain_regex = get_domain_regex_by_log_type(domain, mandatory_log_type)

        if domain_regex is None:
            logger.warning(f"No regex pattern found for domain={domain}, log_type={mandatory_log_type}")
            return logs_dir

        regex_pattern = re.compile(domain_regex, re.IGNORECASE)

        for root, dirs, files in os.walk(input_logs_dir):
            for _file in files:
                full_path = os.path.join(root, _file)
                if regex_pattern.match(full_path):
                    matching_files.append(full_path)

        if matching_files:
            if len(matching_files) > 1:
                logger.info(f"Found {len(matching_files)} matching files for {mandatory_log_type}: {matching_files}")
                if pick_latest_only:
                    latest_file = _get_latest_file(matching_files)
                    logger.info(f"Picking latest file: {latest_file}")
                    logs_dir[mandatory_log_type] = [latest_file]
                else:
                    logger.info(f"Returning all {len(matching_files)} matching files (pick_latest_only=False)")
                    logs_dir[mandatory_log_type] = matching_files
            else:
                logs_dir[mandatory_log_type] = matching_files
    else:
        logger.warning(f"{input_logs_dir} does not exist, no logs are found...")

    logger.info(f"Logs dict after browsing from {input_logs_dir} :: {logs_dir} :: log type:{mandatory_log_type}")
    return logs_dir


def collect_logs_for_scrambling_verification(logs_dict: Dict[str, List[str]],
                                             mandatory_log_type: str,
                                             remote_host: str) -> Dict[str, List[str]]:
    """
    Collect logs from BTS according to mandatory log types and input logs_dict state.
    :param logs_dict:            Logs dict consistent with returned by :func:`check_for_existing_logs_in_dir.py`
    :param mandatory_log_type:   Log type which must be:
                                 - already present in input logs_dict
                                 - collected by this function
    :param remote_host:          IP address used to connect to BTS
    :return:                     Logs dict updated for collected logs
    """

    if mandatory_log_type not in logs_dict:
        logger.info(f'Input type={mandatory_log_type} not found, start collecting...')
        lc = LogsCollector(log_type=mandatory_log_type)
        if 'nop' in mandatory_log_type:
            collected_logs = lc.collect_logs_on_vm()
        else:
            collected_logs = lc.collect_logs_on_vm(remote_host=remote_host)
        logs_dict[mandatory_log_type] = collected_logs
    logger.info(f"Logs dict after collection :: {logs_dict}")
    return logs_dict


def prepare_logs_for_scrambling_verification(logs_dict: Dict[str, List[str]], pkg_prefix: str, log_purpose: str) -> Dict[str, str]:
    """
    Steps:
    1. Create processing dir on VM if not exists
    2. For every log's type and log files in logs_dict:
        - copy logs with target names into processing dir
        - pack all logs from one type into archive, if it's applicable, use pkg_prefix for archive
    :param logs_dict:  Logs dict consistent with returned by :func:`collect_logs_for_scrambling_verification.py`
    :param pkg_prefix: Prefix name for archives, i.e.
                       SBTS23R2_ENB_0000_000588_000000_+23-04-2023-23:30:44+CRT_ASIL_ABIO_pack_2
    :param log_purpose:Determines the additional log preparation before sending.
                       Depending on different CNIs, the format/filenames/structure might differ.
    :return:           Dict with packed logs, for example: {'__snapshot__':
                        '/home/ute/scrambling_processing_dir/SBTS23R2_ENB_0000_000588_000000_
                        +23-04-2023-23:30:44+CRT_ASIL_ABIO_pack_2__snapshot__.zip',
                        '__syslog__': '/home/ute/scrambling_processing_dir/SBTS23R2_ENB_0000_000588_000000_
                        +23-04-2023-23:30:44+CRT_ASIL_ABIO_pack_2__syslog__.zip', }
    """
    processing_dir = os.path.expanduser(os.path.join('~', 'scrambling_processing_dir'))
    packed_logs_dict = {}
    if not os.path.exists(processing_dir):
        os.makedirs(processing_dir)
    for logs_type, logs in logs_dict.items():
        lp = LogsPreparer(logs=logs, logs_type=logs_type, log_purpose=log_purpose)
        lp.copy_logs_into_processing_dir_with_new_names(processing_dir)
        logs_archive = lp.pack_logs_into_archive(pkg_prefix=pkg_prefix)
        packed_logs_dict[logs_type] = logs_archive
    logger.info(f"Logs dict after preparation :: {logs_dict} :: pkg_prefix:{pkg_prefix}")
    return packed_logs_dict


def send_logs_for_scrambling_verification(logs_dict: Dict[str, str], log_purpose: str):
    """
    Send the logs into Log scrambling proxy VM target directory: /home/ute/snapshots
    :param logs_dict: Logs dict consistent with returned by :func:`prepare_logs_for_scrambling_verification.py`
    :param log_purpose:  DEPRECATED, left for compatibility with SISO
    """
    ssh = None
    sftp = None

    try:
        # Try primary VM first, fallback to backup
        VM_IP = PROXY_VM_IPV4 if sftp_connection_available(PROXY_VM_IPV4, PROXY_VM_LOGIN, PROXY_VM_PASSWORD) else PROXY_VM_IPV4_BACKUP
        logger.info(f"Using proxy VM: {VM_IP}")

        # Establish SSH connection with timeout
        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        ssh.connect(VM_IP, username=PROXY_VM_LOGIN, password=PROXY_VM_PASSWORD, timeout=30)

        for log_type, logs_pkg in logs_dict.items():
            try:
                # Validate source file exists
                if not os.path.exists(logs_pkg):
                    logger.error(f"Source log file does not exist: {logs_pkg}")
                    continue

                logs_pkg_remote = os.path.expanduser(os.path.join('~', 'snapshots', os.path.basename(logs_pkg)))
                logger.info(f"Transferring {log_type}: {logs_pkg} -> {logs_pkg_remote}")

                # Create remote directory with error handling
                try:
                    stdin, stdout, stderr = ssh.exec_command(f"mkdir -p {os.path.dirname(logs_pkg_remote)}", timeout=30)
                    exit_status = stdout.channel.recv_exit_status()
                    if exit_status != 0:
                        stderr_output = stderr.read().decode('utf-8').strip()
                        logger.warning(f"mkdir command returned exit status {exit_status}: {stderr_output}")
                except Exception as e:
                    logger.error(f"Failed to create remote directory for {log_type}: {str(e)}")
                    continue

                # SFTP file transfer with error handling
                try:
                    sftp = ssh.open_sftp()
                    # Set timeout for SFTP operations
                    channel = sftp.get_channel()
                    if channel:
                        channel.settimeout(300)  # 5 minutes for file transfer

                    # Get file size for logging
                    file_size = os.path.getsize(logs_pkg)
                    logger.info(f"Uploading file {logs_pkg} (size: {file_size} bytes)")

                    sftp.put(logs_pkg, logs_pkg_remote)
                    logger.info(f"Successfully uploaded {log_type} to {logs_pkg_remote}")

                except Exception as e:
                    logger.error(f"SFTP transfer failed for {log_type} ({logs_pkg}): {str(e)}")
                    continue

                finally:
                    if sftp:
                        try:
                            sftp.close()
                            sftp = None
                        except Exception as e:
                            logger.warning(f"Failed to close SFTP connection for {log_type}: {str(e)}")

            except Exception as e:
                logger.error(f"Failed to process log {log_type}: {str(e)}")
                continue

    except Exception as e:
        logger.error(f"Failed to establish SSH connection or general error: {str(e)}")

    finally:
        # Clean up connections
        if sftp:
            try:
                sftp.close()
            except Exception as e:
                logger.warning(f"Failed to close final SFTP connection: {str(e)}")

        if ssh:
            try:
                ssh.close()
            except Exception as e:
                logger.warning(f"Failed to close SSH connection: {str(e)}")

        # Always attempt to clear directories, even if upload failed
        try:
            clear_directories(DIRECTORIES_TO_CLEAR)
            logger.info("Successfully cleared processing directories")
        except Exception as e:
            logger.error(f"Failed to clear directories: {str(e)}")


def execute_proxy_script_on_vm_for_logs(logs_dict: Dict[str, str], team_name: str, processing_timestamp: str):
    """
    Execution command example:
    cd ~/proxy_script && source venv/bin/activate &&
    python proxy_script.py /home/ute/snapshots/
    SBTS23R2_ENB_0000_000588_000000_+23-04-2023-23:30:44+CRT_ASIL_ABIO_pack_2__snapshot__.zip TRSSEC __snapshot__
    23-04-2023-23:33:42
    :param logs_dict:  Logs dict consistent with returned by :func:`prepare_logs_for_scrambling_verification.py`
    :param team_name:               Delivery team name, i.e. PZ3WRO4
    :param processing_timestamp:    Timestamp related to logs collection starting time. Timestamp should be exact for
                                    all log types collected from single BTS test suite execution.
    """
    ssh = None
    try:
        domain = get_domain(team_name)
        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        # Add connection timeout
        ssh.connect(PROXY_VM_IPV4, username=PROXY_VM_LOGIN, password=PROXY_VM_PASSWORD, timeout=30)

        for artifact_type, artifact_path in logs_dict.items():
            try:
                artifact_name = os.path.basename(artifact_path)
                artifact_path_on_vm = os.path.expanduser(os.path.join('~', 'snapshots', artifact_name))
                cmd = (f"cd ~/proxy_script && source venv/bin/activate && python proxy_script.py {artifact_path_on_vm} "
                       f"{domain} {artifact_type} {processing_timestamp}")
                logger.info(f"Execute cmd: {cmd}")

                # Execute command with timeout
                stdin, stdout, stderr = ssh.exec_command(cmd, timeout=300)

                # Set timeout for reading operations
                stdout.channel.settimeout(60)
                stderr.channel.settimeout(60)

                # Read the output with timeout protection
                stdout_str = stdout.read().decode('utf-8').strip()
                stderr_str = stderr.read().decode('utf-8').strip()
                exit_status = stdout.channel.recv_exit_status()

                # Log everything - success or failure
                logger.info(f"Command for {artifact_type} completed with exit status: {exit_status}")
                if stdout_str:
                    logger.info(f"STDOUT for {artifact_type}:\n{stdout_str}")
                if stderr_str:
                    if exit_status != 0:
                        logger.error(f"STDERR for {artifact_type}:\n{stderr_str}")
                    else:
                        logger.warning(f"STDERR for {artifact_type}:\n{stderr_str}")

            except Exception as e:
                logger.error(f"Failed to execute command for {artifact_type}: {str(e)}")

    except Exception as e:
        logger.error(f"SSH connection or setup failed: {str(e)}")

    finally:
        if ssh:
            try:
                ssh.close()
            except Exception as e:
                logger.error(f"Failed to close SSH connection: {str(e)}")
